INSERT INTO itinerary_revisions (id, itinerary_id, version_number, parent_revision_id, milestone_label, change_summary, save_type, snapshot, snapshot_checksum, created_at) VALUES
('f8d5d76b-fc96-b322-8354-36268df60aa6', '7ed18b64-4f16-65af-0f63-174b1037c868', 1, NULL, 'Imported package content', 'Imported from 11 Days Rajasthan Tour for Website  - Updated.docx', 'manual'::revision_save_type, '{"header": {"title": "11 Days Jaipur-Ajmer/Pushkar-Kumbhalgarh-Udaipur-Jodhpur & Jaisalmer Tour Package", "subtitle": "Jaipur-Ajmer/Pushkar-Kumbhalgarh-Udaipur-Jodhpur & Jaisalmer", "tour_code": "DR066", "duration_label": "10 Night / 11 Days", "alternate_titles": []}, "client": {"title": "Mr", "client_name": "Website Package", "email": null, "email2": null, "phone": null, "adults": 2, "children_5_12": 0, "children_below_5": 0, "rooms": 1, "extra_beds": 0, "travel_date": null, "food_preference": null, "special_requests": null}, "days": [{"day_uuid": "294822ed-de66-5736-b2ff-c0a306ff1fa7", "day_number": 1, "day_title": "Arrival in Jaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Jaipur also known as Pink City, it fascinates with its royal palaces, famous forts, and colorful markets. Experience the royal glory and cultural prosperity of Rajasthan''s capital.\nUpon arrival at Jaipur Railway station/Airport, our representative will greet you. Check-in at the hotel. Relax and in the evening, explore modern attractions of the Pink City:\nStatue Circle - Iconic Monument in Jaipur\nBirla Auditorium & Planetarium - Hub of Cultural Events\nVidhan Sabha - Legislative Assembly of Rajasthan\nBirla Mandir - Marble Splendor in Jaipur\nJawahar Kala Kendra - Artistic Hub of Jaipur\nEnjoy a Rajasthani dinner with folk dance and cultural music at a rural atmosphere resort. Overnight stay in Jaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": false, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "938aa15f-f7ad-e3ca-3de6-d20f21675691", "day_number": 2, "day_title": "Jaipur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, explore the old Pink City:\nHawa Mahal - Palace of Winds Architectural Marvel\nCity Palace - Royal Residence of Jaipur\nObservatory / Jantar Mantar - Historic Astronomical Instruments\nJal Mahal - Palace in the Middle of the Lake\nAmer Fort - Ancient Hill Fort Grandeur\nNahargarh Fort & Places - Scenic Fort with History\nIn the evening, witness the spectacular Light & Sound show at Amer Fort. Overnight stay in Jaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "bed8a083-9181-9e51-a356-46c8d0c56eb7", "day_number": 3, "day_title": "Jaipur to Ajmer/Pushkar", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Pushkar is renowned for its sacred Pushkar Lake and the Brahma Temple, Pushkar is a vibrant pilgrimage site. Enjoy the lively Pushkar Camel Fair and the town''s bohemian vibe.\nAfter breakfast, proceed to Ajmer and Pushkar. Check-in at the hotel and visit:\nDargah of Khwaja Muin-ud-din Chisti at Ajmer - Sacred Sufi Shrine in Ajmer\nLord Brahma Temple at Pushkar - Hindu Pilgrimage Icon\nOvernight stay in Pushkar.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Pushkar", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "c927f4f0-a890-38e1-a654-2f3465cc2045", "sort_order": 0, "title": "Ajmer", "description": "A spiritual hub, Ajmer is home to the revered Ajmer Sharif Dargah. Experience the city''s rich religious heritage, bustling markets, and serene Ana Sagar Lake.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "708930b1-4453-cc3c-5ef3-535d1bbe815e", "day_number": 4, "day_title": "Pushkar to Kumbhalgarh to Udaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, journey towards Udaipur via Kumbhalgarh. Kumbhalgarh is famous for its formidable fort and expansive walls, Kumbhalgarh stands as a testament to Rajasthan''s martial legacy. Explore the UNESCO World Heritage site and its intricate architecture.\nKumbhalgarh Fort - Majestic Fortress of Rajasthan\nArrive in Udaipur, check-in at the hotel. Overnight stay in Udaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Kumbhalgarh", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "bdd7ecf5-ef50-1ebf-635c-4cd72ba5981c", "day_number": 5, "day_title": "Udaipur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Udaipur also known as the \"City of Lakes,\" it enchants with its serene waters, grand palaces, and romantic atmosphere. Visit the exquisite City Palace and enjoy a boat ride on Lake Pichola.\nAfter breakfast, explore the Lake City''s highlights:\nCity Palace - Royal Residence by Lake\nPratap Smarak - Memorial to a Hero\nBhartiya Lok Kala Mandal - Cultural Museum\nSaheliyon ki Bari - Garden of the Maidens\nJagdish Temple - Sacred Hindu Shrine\nBagore ki Haveli - Historic Mansion on Lake\nShilp Gram - Crafts Village\nFateh Sagar Lake - Scenic Water Body\nOvernight stay in Udaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Udaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "d21e2018-01e7-c3aa-241a-27b18436b869", "day_number": 6, "day_title": "Udaipur to Mount Abu Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Mount Abu is Rajasthan''s only hill station, Mount Abu offers a refreshing retreat with cool climate, lush greenery, and scenic viewpoints. Visit the famous Dilwara Temples and enjoy the peaceful Nakki Lake.\nAfter breakfast, proceed to Mount Abu:\nDelwara Temple - Exquisite Jain Temples\nVedi Temple - Spiritual Oasis\nNakki Lake - Tranquil Waterbody\nSunset Point - Mesmerizing Evening Views\nTod Rock - Historical Landmark\nGuru Shikhar - Highest Peak in Aravalli\nAchalgarh Mahadev Temple - Ancient Temple\nBrahma Kumari Ashram - Spiritual Retreat\nOvernight stay in Mount Abu.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Mount Abu", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "ecaa54ac-f781-98ed-73ef-e704fccce61f", "day_number": 7, "day_title": "Mount Abu to Ranakpur to Jodhpur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, depart for Jodhpur via Ranakpur:\nRanakpur Jain Temples - Architectural Marvels\nArrive in Jodhpur, check-in at the hotel. Overnight stay in Jodhpur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Mount Abu", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "f2b4c595-3304-0344-7f3c-79a467541b09", "day_number": 8, "day_title": "Jodhpur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, explore the Blue City''s attractions. The \"Blue City\" Jodhpur boasts the majestic fort and a sea of blue houses. Discover its rich history, exciting shopping markets, and scenic views of the Thar Desert.\nUmaid Bhawan Palace Museum - Opulent Palace Turned Museum\nJaswant Thada - Memorial of White Marble\nMehrangarh Fort - Impregnable Hill Fort\nClock Tower & Markets - Busy Bazaars\nOvernight stay in Jodhpur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jodhpur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "e62a7a35-f3a1-ca73-25d6-e1772cfea397", "day_number": 9, "day_title": "Jodhpur to Jaisalmer", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, drive to Jaisalmer. Jaisalmer mesmerizes with its yellow sandstone architecture and the magnificent Jaisalmer Fort. Experience desert safaris, ornate havelis, and a glimpse into desert life.\nCheck-in at the hotel and visit:\nWar Museum - Memorial of Valor\nGadisar Lake - Artificial Water Reservoir\nVyas Chhatri - Architectural Gem\nOvernight stay in Jaisalmer.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "2fa7b764-22fe-cd8c-9171-45a4ca5d0971", "day_number": 10, "day_title": "Jaisalmer Sightseeing & Desert Experience", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, explore Jaisalmer:\nJaisalmer Fort & Palaces - Golden Citadel of Rajasthan\nJain Temples - Intricate Marvels of Faith\nPatwon ki Haveli - Historic Merchant Residence\nSalim Singh ki Haveli - Architectural Grandeur\nNathmal ki Haveli - Craftsmanship in Stone\nExperience a night in tents at the sand dunes desert with cultural programs, camel rides, bonfire, sunset, and dinner. Overnight stay at Desert Camp.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "break