('0b0cd739-f706-6342-cca0-275c631243ce', '7b9d9953-bb21-8336-8463-6b3b53f96f2a', 1, NULL, 'Imported package content', 'Imported from 12 Days Rajasthan Tour for Website - Updated.docx', 'manual'::revision_save_type, '{"header": {"title": "12 Days Jaipur-Pushkar-Bikaner-Jaisalmer-Jodhpur-Mount Abu-Udaipur-Ranthambhore Tour Package", "subtitle": "Jaipur-Pushkar-Bikaner-Jaisalmer-Jodhpur-Mount Abu-Udaipur-Ranthambhore", "tour_code": "DR068", "duration_label": "11 Night / 12 Days", "alternate_titles": []}, "client": {"title": "Mr", "client_name": "Website Package", "email": null, "email2": null, "phone": null, "adults": 2, "children_5_12": 0, "children_below_5": 0, "rooms": 1, "extra_beds": 0, "travel_date": null, "food_preference": null, "special_requests": null}, "days": [{"day_uuid": "0d1667a9-e342-db45-26d2-014e703db1e1", "day_number": 1, "day_title": "Arrival in Jaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Welcome to Jaipur! known as Pink City, it fascinates with its royal palaces, famous forts, and colorful markets. Experience the royal glory and cultural prosperity of Rajasthan''s capital.\nOur representative will greet you at the Jaipur Railway Station or Airport. After arriving, check in at your hotel and relax for a bit. In the evening, we will visit some modern attractions of the Pink City:\nStatue Circle - Symbol of Rajasthan''s Proud Heritage\nBirla Auditorium & Planetarium - Explore Stars and Scientific Wonders\nVidhan Sabha - Heart of Rajasthan''s Democracy\nBirla Mandir - Divine Peace Amidst Urban Rush\nJawahar Kala Kendra - Art and Culture in Harmony\nLater, enjoy a delicious Rajasthani dinner at a resort with pleasant folk music and cultural dances in a village setting. Overnight stay at your hotel in Jaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": false, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "4d6e227f-6752-1793-6d48-463ee88a5cf0", "day_number": 2, "day_title": "Jaipur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, we will explore the old pink city and visit these places:\nHawa Mahal - Wind Palace of Pink City\nCity Palace - Royal Splendor in Every Corner\nObservatory / Jantar Mantar - Ancient Wisdom Meets Astronomical Marvel\nJal Mahal - Palace Floats on Tranquil Waters\nAmer Fort - Majestic Fortress of Rich History\nNahargarh Fort & Palace - Panoramic Views, Regal Architecture United\nIn the evening, enjoy a Light & Sound show at Amer Fort, showcasing the magnificent history of Rajasthan. Overnight stay at your hotel in Jaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "0b482f41-47a6-4a75-b8a5-a4388c17bd55", "day_number": 3, "day_title": "Jaipur – Ajmer/Pushkar", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Pushkar is renowned for its sacred Pushkar Lake and the Brahma Temple, Pushkar is a vibrant pilgrimage site. Enjoy the lively Pushkar Camel Fair and the town''s bohemian vibe.\nAfter breakfast, we will head to Pushkar. Upon arrival, check in at your hotel. Then, we will visit Ajmer and Pushkar, famous pilgrimage centers:\nDargah of Khwaja Muin-ud-din Chisti at Ajmer - Spiritual Haven of Peaceful Reflection\nLord Brahma Temple at Pushkar - Sacred Hub of Divine Presence\nOvernight stay at your hotel in Pushkar.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Pushkar", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "b8d5906c-5ef2-2ed2-f143-4ae13738abc3", "sort_order": 0, "title": "Ajmer", "description": "A spiritual hub, Ajmer is home to the revered Ajmer Sharif Dargah. Experience the city''s rich religious heritage, bustling markets, and serene Ana Sagar Lake.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "700dfcb1-78c8-119d-196f-001737093453", "day_number": 4, "day_title": "Jaipur - Bikaner", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, we will check out from the hotel and transfer to Bikaner, a city in the Thar Desert. Upon arrival, check in at your hotel. We will visit amazing places in Bikaner:\nJunagarh Fort - Ancient Stronghold of Rajput Valor\nCamel Breeding Farm - Nurturing the Ship of Desert\nKarni Mata Temple - Holy Sanctuary of Revered Rats\nOvernight stay at your hotel in Bikaner.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Bikaner", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "49c75f23-aa22-5d3a-4ec9-f3ef82a06fd2", "day_number": 5, "day_title": "Bikaner - Jaisalmer", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, we will drive to Jaisalmer and check in at your hotel. After freshening up, we will visit the Golden City:\nWar Museum - Echoes of Valor and Sacrifice\nGadisar Lake - Tranquil Oasis in Desert Sands\nVyas Chhatri - Architectural Serenity Amidst Desert Beauty\nOvernight stay at your hotel in Jaisalmer.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "c9eb423e-38e9-9cc0-9a5e-0be5f47916c5", "sort_order": 0, "title": "Jaisalmer", "description": "The \"Golden City\" Jaisalmer mesmerizes with its yellow sandstone architecture and the magnificent Jaisalmer Fort. Experience desert safaris, ornate havelis, and a glimpse into desert life.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "c9ce3a5a-9e77-69e7-4f3b-38e3db30af9e", "day_number": 6, "day_title": "Sightseeing & Jaisalmer Desert", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, we will explore Jaisalmer, the golden city of Rajasthan:\nJaisalmer Fort & Palaces - Golden Citadel of Desert Majesty\nJain Temples - Sacred Marvels of Intricate Carvings\nPatwon Ki Haveli - Exquisite Architectural Heritage of Jaisalmer\nSalim Singh Ki Haveli - Elegant Residence in Desert Splendor\nNathmal Ki Haveli - Symphony of Sandstone Artistry\nLater, experience a night in the desert with cultural programs, a camel ride, bonfire, sunset, and dinner. Overnight stay at the Desert Camp.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "b79ce9d6-970c-f9be-e4e6-f5e0c80411c7", "day_number": 7, "day_title": "Jaisalmer – Jodhpur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "The \"Blue City\" Jodhpur boasts the majestic fort and a sea of blue houses. Discover its rich history, exciting shopping markets, and scenic views of the Thar Desert.\nAfter breakfast, we will check out from the desert camp and move towards Jodhpur. After checking in at your hotel, we will visit the Blue City:\nUmaid Bhawan Palace Museum - Grandeur Preserved in Royal Legacy\nJaswant Thada - Marble Serenity Amidst History\nMehrangarh Fort - Guardian of Jodhpur''s Legacy\nClock Tower & Markets - Pulse of Jodhpur''s Vibrant Culture\nOvernight stay at your hotel in Jodhpur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "990f8d9a-e6f5-05c0-8ecc-c82cefce0882", "day_number": 8, "day_title": "Udaipur – Mount Abu Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Mount Abu is Rajasthan''s only hill station, Mount Abu offers a refreshing retreat with cool climate, lush greenery, and scenic viewpoints. Visit the famous Dilwara Temples and enjoy the peaceful Nakki Lake.\nAfter breakfast, we will head to Mount Abu. Check in at your hotel, and then visit the major attractions of Mount Abu:\nDelwara Temple - Divine Elegance in Marble\nVedi Temple - Spiritual Haven Amidst Hills\nNakki Lake - Tranquil Mirror of Nature\nSunset Point - Nature''s Canvas Unfolding Beauty\nToad Rock - Nature''s Art\nGuru Shikhar - Peak of Spiritual Solace\nAchalgarh Mahadev - Ancient Spiritual Resonance\nBrahma Kumari Ashram - Spiritual Retreat in Tranquility\nOvernight stay at your hotel in Mount Abu.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Mount Abu", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "4e277ce6-e657-eafd-adcb-dd43695bd33b", "day_number": 9, "day_title": "Mount Abu - Ranakpur - Udaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, we will proceed to Udaipur. On the way, we will visit Ranakpur Jain Temples, known for their splendid architectural style. Later, we will transfer to Udaipur and check in at your hotel. Overnight stay at your hotel in Udaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Mount Abu", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "fd8a4b2e-e2e6-897d-37ca-486be59a4cba", "day_number": 10, "day_title": "Udaipur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Udaipur also known as the \"City of Lakes,\" it enchants with its serene waters, grand palaces, and romantic atmosphere. Visit the exquisite City Palace and enjoy a boat ride on Lake Pichola.\nAfter breakfast, we will explore every nook and corner of the Lake City, including:\nCity Palace - Palatial Marvel by Lake Pichola\nJagdish Temple - Architectural Gem of Udaipur\nBhartiya Lok Kala Mandal - Cultural Heritage in Living Art\nPratap Smarak - Heroic Tribute to Maharana Pratap\nShilp Gram - Artisan Village of Crafts\nBagore Ki Haveli - Timeless Heritage on Lake Shore\nSaheliyon Ki Bari - Garden of Maidens'' Delight\nOvernight stay at your hotel in Udaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Udaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "e5c16431-924f-73cf-9bee-acb1b948a69a", "day_number": 11, "day_title": "Udaipur - Ranthambhore", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, we will drive to Ranthambhore and check in at your hotel. After some relaxation, we will visit the beautiful Ranthambhore National Park