ON CONFLICT (id) DO UPDATE SET package_name = EXCLUDED.package_name, destination = EXCLUDED.destination, slug = EXCLUDED.slug, package_type = EXCLUDED.package_type, package_duration = EXCLUDED.package_duration, status = EXCLUDED.status, updated_at = now();

ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tour_code = EXCLUDED.tour_code, grand_total = EXCLUDED.grand_total, source_package_id = EXCLUDED.source_package_id, updated_at = now();

ON CONFLICT (id) DO UPDATE SET snapshot = EXCLUDED.snapshot, change_summary = EXCLUDED.change_summary;

